import{_ as t,c as o,o as r,ae as a}from"./chunks/framework.CliRSA9F.js";const s="/images/keyword_tracker_overview.webp",y=JSON.parse('{"title":"Keyword Tracker","description":"","frontmatter":{},"headers":[],"relativePath":"features/keyword-tracker.md","filePath":"features/keyword-tracker.md"}'),n={name:"features/keyword-tracker.md"};function i(l,e,u,c,h,d){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="keyword-tracker" tabindex="-1">Keyword Tracker <a class="header-anchor" href="#keyword-tracker" aria-label="Permalink to &quot;Keyword Tracker&quot;">​</a></h1><h2 id="monitor-and-optimize-your-podcast-s-visibility" tabindex="-1">Monitor and Optimize Your Podcast&#39;s Visibility <a class="header-anchor" href="#monitor-and-optimize-your-podcast-s-visibility" aria-label="Permalink to &quot;Monitor and Optimize Your Podcast&#39;s Visibility&quot;">​</a></h2><p>The Keyword Tracker is your ultimate tool to monitor the performance of your podcast across important search terms. It helps you track rankings, analyze trends, and refine your SEO strategy to outperform competitors. In the app&#39;s Search Visibility navigation, this feature appears as the <strong>Tracker</strong> tab (its full name is Keyword Tracker).</p><p><strong>Important</strong>: This feature works with the keywords you track from your <a href="/features/keyword-strategy.html">Keyword Strategy</a>. The Keyword Tracker is primarily for analyzing the performance of <em>already-tracked</em> keywords, but you can also add new keywords and delete existing ones directly on this page. For full keyword planning—saying what each keyword is for (your show, an episode, your brand, a competitor, or a theme)—the Keyword Strategy page remains your central hub.</p><p><img src="'+s+'" alt="Keyword Tracker Dashboard" width="600px" style="display:block;margin:0 auto;"></p><h3 id="features-at-a-glance" tabindex="-1"><strong>Features at a Glance</strong> <a class="header-anchor" href="#features-at-a-glance" aria-label="Permalink to &quot;**Features at a Glance**&quot;">​</a></h3><ol><li><p><strong>Track Keyword Performance Over Time</strong></p><ul><li><p>Visualize keyword ranking trends for your podcast across platforms like Spotify, Apple Podcasts, Amazon Music, and YouTube Music, plus YouTube itself when PodSEO knows your podcast&#39;s YouTube channel (see <a href="#youtube-rankings">YouTube rankings</a> below).</p></li><li><p>Interactive charts display how rankings shift over time, giving you insights into what’s working and what needs improvement.</p></li></ul></li><li><p><strong>View Current Rankings</strong></p><ul><li><p>Quickly check the current results for any keyword by clicking <strong>Top Results</strong> in its row</p></li><li><p>This allows you to see exactly where your podcast or competitors rank for that keyword right now.</p></li></ul></li><li><p><strong>Compare Keywords</strong></p><ul><li><p>Track multiple keywords to identify which ones drive the most visibility and which need optimization</p></li><li><p>Spot trends across platforms and pinpoint growth opportunities.</p></li></ul></li><li><p><strong>Platform and Time Interval Filters</strong></p><ul><li><p>Switch between Spotify, Apple Podcasts, Amazon Music, YouTube Music, and (when available) YouTube to analyze keyword performance on each platform.</p></li><li><p>Adjust the time interval—<strong>Last 15 Days</strong>, <strong>Last 30 Days</strong>, or <strong>Last 10 Weeks</strong>—to focus on short-term trends or longer-term growth.</p></li></ul></li><li><p><strong>Competitive Insights</strong></p><ul><li><p>See which podcasts rank for your tracked keywords and identify competitors dominating key search terms.</p></li><li><p>The table will dynamically add columns for each of your tracked competitors, allowing you to compare rankings side-by-side.</p></li></ul></li><li><p><strong>Volume, Popularity and Difficulty Metrics</strong></p><ul><li><p><strong>Volume (VOL.):</strong> Roughly how many times a month people search for the keyword, shown as a 6-step green meter with six levels: <strong>Very niche</strong> (under 100 searches a month), <strong>Niche</strong> (100–250), <strong>Small</strong> (250–1K), <strong>Medium</strong> (1K–2.5K), <strong>Popular</strong> (2.5K–10K), and <strong>Very popular</strong> (10K+). Hover over the meter (or focus it) to see the level and range, for example &quot;Small · 250–1K searches/mo&quot;. On mobile, each keyword card shows the meter with the range, such as &quot;250–1K/mo&quot;. A clock icon means the keyword hasn&#39;t been measured yet; it fills in after the next periodic check. Niche keywords aren&#39;t a weakness: fewer people search for them, but they&#39;re usually easier to rank for.</p></li><li><p><strong>Popularity (POP.):</strong> How crowded the keyword is on the selected platform: how many shows and episodes already rank for it, from 0-100%. Lower popularity means less competition and more room for your podcast.</p></li><li><p><strong>Difficulty (DIFF.):</strong> Measures how competitive it is to rank for the keyword, helping you prioritize achievable goals.</p></li></ul></li><li><p><strong>Top Results Modal</strong></p><ul><li>Click the &quot;Top Results&quot; button for any keyword to see the top 50 podcasts ranking for that keyword on the selected platform.</li></ul></li><li><p><strong>CSV Download</strong></p><ul><li>Download the currently filtered keyword data as a CSV file for your own analysis. The <strong>Search volume (searches/mo)</strong> column holds each keyword&#39;s monthly range (for example &quot;1K-2.5K&quot;) and is empty for keywords that haven&#39;t been measured yet.</li></ul></li></ol><hr><h3 id="how-to-use" tabindex="-1"><strong>How to Use</strong> <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;**How to Use**&quot;">​</a></h3><ol><li><p><strong>Analyze Rankings</strong><br> Use the interactive chart to track trends over time. Hover over data points to view ranking details for specific dates.</p></li><li><p><strong>Check Current Rankings</strong><br> Click <strong>Top Results</strong> next to a keyword to see the top 50 podcasts currently ranking for it on the selected platform.</p></li><li><p><strong>Compare Competitors</strong><br> Scroll through the table to see which podcasts rank for each keyword. Identify and analyze competitors to refine your strategy.</p></li><li><p><strong>Filter Platforms and Keywords</strong><br> Use platform filters to focus on Spotify, Apple, Amazon Music, YouTube Music, or YouTube data. Toggle individual keywords for more precise insights.</p></li></ol><hr><h3 id="search-countries" tabindex="-1"><strong>Search Countries</strong> <a class="header-anchor" href="#search-countries" aria-label="Permalink to &quot;**Search Countries**&quot;">​</a></h3><p>By default, keyword rankings in Tracker are what a listener in the <strong>United States</strong> would see. Platform search results differ by country — the same keyword can return a different order in the UK, Germany, or Australia — so if your audience is elsewhere, US results may not match what your listeners experience.</p><p>On paid plans you can add search countries per podcast:</p><ol><li>Go to <strong>Settings → Podcasts</strong> and find the <strong>Search countries</strong> row for the podcast. The US is always included; click the <strong>+</strong> button to add another country. Only countries that every supported platform can serve are offered.</li><li>Back in Keyword Tracker, use the <strong>country selector</strong> next to the platform and timeframe filters to switch the chart and table between your tracked countries. The bottom of the Country dropdown also has an <strong>Add countries</strong> link (or <strong>Manage countries</strong> once you&#39;ve added some) that takes you straight to this setting.</li><li>When you first add a country you&#39;ll see a <strong>Collecting</strong> notice — the first rankings for that country land within about 24 hours. If a country&#39;s data hasn&#39;t been refreshed recently, the tracker labels it as possibly out of date; if a platform can&#39;t be searched from that country yet, it says so instead of showing a blank chart.</li></ol><p><strong>Allowance by plan.</strong> Beyond the included US results, paid plans can track additional countries <em>per podcast</em>: Podcaster 1, Producer 5, Agency 10, Enterprise unlimited. Free accounts see US rankings only. If you move to a plan with a smaller allowance, your extra countries stay listed but are flagged <strong>over plan</strong> and stop updating until you remove others; removing a country works on every plan.</p><p>Search countries are separate from the countries used in <a href="/features/my-charts.html">My Charts</a> (chart positions) and from the Apple storefronts listed in <a href="/features/ratings-and-reviews.html">Ratings &amp; Reviews</a>. Adding a search country only affects keyword rankings.</p><p><strong>Why rankings may differ from what you see on your phone.</strong> Your own app shows results for your device&#39;s storefront, language, and — on some platforms — your listening history. PodSEO collects results as a neutral listener in the selected country, so small differences are normal; large, persistent differences usually mean you&#39;re comparing against a country you haven&#39;t added.</p><h3 id="youtube-rankings" tabindex="-1"><strong>YouTube Rankings</strong> <a class="header-anchor" href="#youtube-rankings" aria-label="Permalink to &quot;**YouTube Rankings**&quot;">​</a></h3><p><strong>YouTube</strong> and <strong>YouTube Music</strong> are separate platforms in the tracker. YouTube Music is the podcast directory inside the YouTube Music app, where your show appears as a podcast. <strong>YouTube</strong> is the regular youtube.com search, where people find your videos.</p><p>On YouTube, PodSEO ranks your <strong>channel</strong>: if any of your channel&#39;s videos, playlists, or the channel itself appears in the results for a keyword, the best of those positions is your rank. This shows whether your video content is being found for the same keywords you target on the podcast apps.</p><p>The YouTube option appears for podcasts that PodSEO has linked to a YouTube channel. The most reliable way to make sure your channel is linked is to connect it in <a href="/features/youtube-insights.html">YouTube Insights</a> or <a href="/features/social-publishing.html">Social Publishing</a>; PodSEO can also recognize it from public YouTube information. A few things to know:</p><ul><li>YouTube rankings are collected as a <strong>US</strong> viewer, even if you&#39;ve added other search countries.</li><li>YouTube rankings don&#39;t affect your <a href="/getting-started/visibility-score-explained.html">Visibility Score</a>, which is built from the podcast platforms.</li><li>To see which <em>actual searches</em> bring viewers to your videos (rather than where you rank for your own keywords), use the YouTube searches list in <a href="/features/youtube-insights.html">YouTube Insights</a>.</li></ul><h3 id="why-it-matters" tabindex="-1"><strong>Why It Matters</strong> <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;**Why It Matters**&quot;">​</a></h3><p>The Keyword Tracker provides actionable insights into your podcast’s discoverability. With tools to track performance, compare competitors, and understand rankings across platforms, you can optimize your SEO strategy to grow your audience and outrank competitors.</p><hr><h3 id="pro-tip" tabindex="-1"><strong>Pro Tip</strong> <a class="header-anchor" href="#pro-tip" aria-label="Permalink to &quot;**Pro Tip**&quot;">​</a></h3><p>Check <strong>Top Results</strong> often to stay up-to-date with your current keyword rankings. Use the insights to adapt your release schedules or metadata strategy to gain a competitive edge.</p><h3 id="plan-restrictions" tabindex="-1"><strong>Plan Restrictions</strong> <a class="header-anchor" href="#plan-restrictions" aria-label="Permalink to &quot;**Plan Restrictions**&quot;">​</a></h3><ul><li><strong>Tracked Keywords</strong>: The number of keywords you can track is based on your plan, whatever each keyword is used for. If you exceed your plan&#39;s limit, you will see an &quot;Over-Quota Warning&quot;.</li><li><strong>Chart Display</strong>: All tracked keywords visible in performance charts.</li><li><strong>Historical Data</strong>: Keyword ranking trends over time are available on all plans, using the Last 15 Days, Last 30 Days, and Last 10 Weeks intervals.</li></ul>',30)])])}const g=t(n,[["render",i]]);export{y as __pageData,g as default};
